def encode_amount(dollars: str) -> str:
    s = dollars.strip()
    sign = "-" if s.startswith("-") else "+"
    num = s.lstrip("+-")

    if "." in num:
        whole, frac = num.split(".")
    else:
        whole, frac = num, ""

    if len(frac) > 2:
        frac = frac[:2]
    else:
        frac = frac.ljust(2, "0")

    cents = int(whole or "0") * 100 + int(frac)
    digits = str(cents)

    check = sum(int(ch) for ch in digits) % 10
    return f"{sign}{digits}#{check}"

